CREATE TABLE trivias (
    id BINARY(16) NOT NULL,
    content TEXT NOT NULL,
    movie_id BINARY(16),
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,

    PRIMARY KEY (id),

    CONSTRAINT fk_trivias_movie
        FOREIGN KEY (movie_id)
            REFERENCES movies (id)
);

